<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free BMI Calculator Online','description'=>'Calculate Body Mass Index from height and weight instantly.','url'=>'https://smarttoolz.in/tools/bmi-calculator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">BMI CALCULATOR</span><h1>BMI Calculator</h1><p>Enter your height and weight to calculate your BMI instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Weight (kg)<input id="w" type="number" min="1" step="0.1" placeholder="70"></label><label>Height (cm)<input id="h" type="number" min="1" step="0.1" placeholder="175"></label><button id="go" class="tool-btn">Calculate BMI</button><p id="out" style="margin-top:15px;font-size:22px;font-weight:800"></p></div></section><section class="tool-content-grid"><article class="tool-content-card"><h2>BMI result</h2><p>Below 18.5: underweight · 18.5–24.9: normal range · 25–29.9: overweight · 30+: obesity.</p></article><article class="tool-content-card"><h2>Private</h2><p>Your calculation runs in the browser.</p></article></section></main><script>(()=>{const w=document.getElementById('w'),h=document.getElementById('h'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let W=+w.value,H=+h.value/100;if(!W||!H){o.textContent='Enter valid height and weight.';return}let b=W/(H*H),c=b<18.5?'Underweight':b<25?'Normal range':b<30?'Overweight':'Obesity';o.textContent=`BMI: ${b.toFixed(1)} — ${c}`}})();</script><?php smarttoolz_tool_page_end(); ?>